from sys import stdin, stdout

def read_input():
    input = stdin.read
    data = input().split()

    index = 0
    def next_int():
        nonlocal index
        result = int(data[index])
        index += 1
        return result

    n = next_int()
    k = next_int()

    roads = []
    for _ in range(n - 1):
        x = next_int()
        y = next_int()
        roads.append((x, y))

    return n, k, roads

def write_output(r, companies):
    print(r)
    print(' '.join(map(str, companies)))

def solve(n, k, roads):
    # We need to assign companies to roads such that no city has more than k roads of the same company
    # Let's start with the smallest number of companies and increase until we satisfy the condition

    # Initialize the list of companies with 0s (no company assigned yet)
    companies = [0] * (n - 1)

    # Function to check if the current assignment of companies satisfies the condition
    def is_valid_assignment():
        # Create a dictionary to count the number of roads of each company in each city
        city_company_count = {i: {} for i in range(1, n + 1)}

        # Populate the dictionary based on the current assignment
        for i, (x, y) in enumerate(roads):
            for city in (x, y):
                if company := city_company_count[city].get(companies[i]):
                    company += 1
                else:
                    company = 1
                city_company_count[city][companies[i]] = company

        # Check if any city has more than k roads of the same company
        for city, company_counts in city_company_count.items():
            if any(count > k for count in company_counts.values()):
                return False
        return True

    # Binary search for the minimum number of companies
    left, right = 1, n - 1
    while left < right:
        mid = (left + right) // 2
        if is_valid_assignment():
            right = mid
        else:
            left = mid + 1

    # Assign companies to roads using the found minimum number of companies
    used_companies = set()
    for i in range(n - 1):
        if companies[i] == 0:
            companies[i] = min(left, len(used_companies) + 1)
            used_companies.add(companies[i])

    return left, companies

if __name__ == "__main__":
    n, k, roads = read_input()
    r, companies = solve(n, k, roads)
    write_output(r, companies)

from collections import defaultdict
import sys

def read_input():
    input = sys.stdin.read
    data = input().split()
    n = int(data[0])
    k = int(data[1])
    edges = []
    index = 2
    for _ in range(n - 1):
        x = int(data[index])
        y = int(data[index + 1])
        edges.append((x, y))
        index += 2
    return n, k, edges

def find_min_companies(n, k, edges):
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    def dfs(node, parent, visited, component):
        nonlocal comp_index
        if node in visited:
            return False
        visited.add(node)
        component[node] = comp_index
        for neighbor in graph[node]:
            if neighbor != parent:
                if not dfs(neighbor, node, visited, component):
                    return False
        return True

    visited = set()
    comp_index = 0
    component = [-1] * (n + 1)
    for i in range(1, n + 1):
        if i not in visited:
            comp_index += 1
            if not dfs(i, -1, visited, component):
                return -1

    count = defaultdict(int)
    for comp in component:
        count[comp] += 1

    companies = list(count.values())
    companies.sort(reverse=True)

    if len(companies) <= k:
        return 1, [1] * (n - 1)

    total_comp = len(companies)
    if k == 0:
        if max(companies) > 1:
            return -1, []

    result = []
    assigned = [False] * (n + 1)
    for i in range(1, n + 1):
        if not assigned[i]:
            assigned[i] = True
            current_comp = 1
            for j in range(total_comp):
                if companies[j] > 1 and component[i] != component[graph[i][0]]:
                    current_comp += 1
                    companies[j] -= 1
                    if companies[j] == 1:
                        total_comp -= 1
                        companies.pop(j)
                        break
            result.append(current_comp)

    return len(result), result

def main():
    n, k, edges = read_input()
    r, c = find_min_companies(n, k, edges)
    if r == -1:
        print("No valid solution")
    else:
        print(r)
        print(*c)

if __name__ == "__main__":
    main()
